            grid-template-columns: repeat(3, 1fr);
            gap: 2rem;
            max-width: 1200px;
            margin: 4rem auto;
            padding: 0 2rem;
        }
        .feature-card {
            text-align: center;
            padding: 2rem;
            border: 1px solid #eee;
            border-radius: 10px;
            transition: transform 0.3s;
        }
        .feature-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.05);
        }
        .feature-card h3 {
            color: var(--primary-color);
            margin-bottom: 1rem;
        }
